/**
 * AVIF/WebP <picture> for the variants generated by scripts/prepare-images.mjs
 * (`/images/{name}-{width}.{avif|webp}`). `width`/`height` are the intrinsic ratio, so the
 * browser reserves the space before the file arrives (no layout shift).
 */
export function ResponsiveImage({
  name,
  widths,
  width,
  height,
  alt,
  sizes,
  className,
  priority = false,
}: {
  name: string
  widths: number[]
  width: number
  height: number
  alt: string
  sizes: string
  className?: string
  priority?: boolean
}) {
  const srcSet = (format: "avif" | "webp") => widths.map((w) => `/images/${name}-${w}.${format} ${w}w`).join(", ")
  const fallback = widths[Math.min(1, widths.length - 1)]

  return (
    <picture>
      <source type="image/avif" srcSet={srcSet("avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet("webp")} sizes={sizes} />
      <img
        src={`/images/${name}-${fallback}.webp`}
        alt={alt}
        width={width}
        height={height}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        className={className}
      />
    </picture>
  )
}
